         if(!nreset)
            ready_counter[8:0] <= 'b0;   
         else
            ready_counter[8:0] <= ready_counter+1'b1;         
         assign ready_random = ready_counter[5] ^ ready_counter[4];
      end
      else
      begin
         assign ready_random = 1'b0;
      end // else: !if(WAIT)
   endgenerate

endmodule

